let lang='en',theme='dark',projects=[],currentId,activePanel='design',device='desktop',saveTimer,previewTimer,toastTimer,job=null,jobTimer,latestPreview='',storageOkay=true,storageReadFailed=false,defaultsVersion=0;
const STORE='pocol-studio-projects-v1',SETTINGS='pocol-studio-settings-v1';
try{const s=JSON.parse(localStorage.getItem(SETTINGS)||'{}');lang=s.lang==='ar'?'ar':'en';defaultsVersion=Number(s.defaultsVersion)||0;theme=s.theme==='light'?'light':'dark';currentId=s.currentId;const v=JSON.parse(localStorage.getItem(STORE)||'[]');if(Array.isArray(v))projects=v.slice(0,25).map(validateProject);}catch{storageOkay=false;storageReadFailed=true;}
if(defaultsVersion<2){let migrated=false;projects=projects.map(p=>{const next=upgradeLegacyStarter(p);if(next!==p)migrated=true;return next;});if(migrated)lang='en';}
if(!projects.length)projects=[newProject('personal')];if(!projects.some(p=>p.id===currentId))currentId=projects[0].id;
const t=k=>strings[lang][k]||k;const project=()=>projects.find(p=>p.id===currentId);const bytes=n=>n>=1048576?(n/1048576).toFixed(2)+' MiB':n>=1024?(n/1024).toFixed(1)+' KB':n+' B';
function settings(){try{localStorage.setItem(SETTINGS,JSON.stringify({lang,theme,currentId,defaultsVersion}));}catch{}}
function toast(text,error=false){clearTimeout(toastTimer);const el=$('#toast');el.textContent=text;el.classList.toggle('error-text',error);el.hidden=false;toastTimer=setTimeout(()=>el.hidden=true,5000);}
function errorText(e){return strings[lang][e?.message]||e?.message||t('unknownError');}
function persist(){clearTimeout(saveTimer);try{if(storageReadFailed)throw Error('Preserve unreadable stored draft');localStorage.setItem(STORE,JSON.stringify(projects));defaultsVersion=2;storageOkay=true;$('#save-state').textContent=t('saved');$('#save-state').classList.remove('error-text');}catch{storageOkay=false;$('#save-state').textContent=t('saveFailed');$('#save-state').classList.add('error-text');}settings();}
function changed(){project().updated=Date.now();$('#save-state').textContent=t('saving');saveTimer=setTimeout(persist,400);clearTimeout(previewTimer);previewTimer=setTimeout(renderPreview,120);renderHeading();}
function setLocale(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.documentElement.dataset.theme=theme;$$('[data-t]').forEach(e=>e.textContent=t(e.dataset.t));$('#lang-btn').textContent=lang==='ar'?'English':'العربية';$('#save-state').textContent=t(storageOkay?'saved':'saveFailed');render();settings();}
function renderHeading(){const p=project();$('#project-title').textContent=p.name;$('#crumb-name').textContent=p.name;$('#draft-label').textContent=t(p.published?(p.published.attached?'attached':'published'):'draft');$('#publish-btn span:last-child').textContent=t(job?'resumePublish':p.published?'update':'publish');$('#project-select').innerHTML=projects.map(p=>`<option value="${h(p.id)}" ${p.id===currentId?'selected':''}>${h(p.name)}</option>`).join('');}
function inputField(key,label,value,kind='input',section=null){const attr=section===null?`data-field="${key}"`:`data-section="${section}" data-key="${key}"`;return`<div class="field"><label for="${section===null?'field-'+key:'section-'+section+'-'+key}">${h(t(label))}</label>${kind==='textarea'?`<textarea id="${section===null?'field-'+key:'section-'+section+'-'+key}" ${attr} rows="${key==='title'?2:3}">${h(value)}</textarea>`:`<input id="field-${key}" ${attr} value="${h(value)}" maxlength="${key==='name'?100:500}">`}</div>`;}
function renderInspector(){const p=project();let html=`<div class="field-group"><h3><span>◇</span>${t('identity')}</h3>${inputField('name','projectName',p.name)}`;
if(p.mode==='files'){html+=`<p class="help-text">${t('importedNotice')}</p><div class="field"><label for="entry-file">${t('entryFile')}</label><select id="entry-file">${p.files.filter(f=>mimeFor(f.path)==='text/html').map(f=>`<option value="${h(f.path)}" ${f.path===p.entry?'selected':''}>${h(f.path)}</option>`).join('')}</select></div></div>`;}
else{html+=`${inputField('brand','brandName',p.brand)}<div class="field"><label for="page-language">${t('pageLanguage')}</label><select id="page-language"><option value="ar" ${p.lang==='ar'?'selected':''}>العربية</option><option value="en" ${p.lang==='en'?'selected':''}>English</option></select></div><div class="field"><label>${t('logo')}</label><div class="logo-control"><span class="logo-preview">${p.logo?`<img src="data:${p.logo.mime};base64,${p.logo.base64}" alt="">`:'＋'}</span><div><button class="text-button" id="upload-logo">${t('uploadLogo')}</button><div class="logo-caption">${t('logoHint')}</div></div>${p.logo?`<button class="small-btn" id="remove-logo">${t('remove')}</button>`:''}</div></div></div><div class="field-group"><h3><span>≡</span>${t('content')}</h3>${inputField('eyebrow','eyebrow',p.eyebrow)}${inputField('title','title',p.title,'textarea')}${inputField('description','description',p.description,'textarea')}${inputField('button','buttonText',p.button)}</div><div class="field-group"><h3><span>◉</span>${t('appearance')}</h3><div class="field"><label for="accent-color">${t('accent')}</label><div class="color-row"><input type="color" id="accent-color" value="${p.color}"><span id="accent-code">${p.color.toUpperCase()}</span></div><div class="swatches">${['#187b68','#147d8d','#6743c3','#ba6739','#2d4d91','#383d42'].map(c=>`<button class="swatch ${p.color===c?'active':''}" style="--swatch:${c}" data-color="${c}" aria-label="${c}"></button>`).join('')}</div></div><div class="field"><label for="surface-color">${t('background')}</label><div class="color-row"><input type="color" id="surface-color" value="${p.surface}"><span id="surface-code">${p.surface.toUpperCase()}</span></div></div></div><div class="field-group"><div class="sections-title"><h3><span>▤</span>${t('sections')}</h3><span class="help-text">${p.sections.length}/20</span></div>${p.sections.map((s,i)=>`<details class="section-item"><summary><span class="grip">⠿</span><span class="section-name">${h(s.title||t(s.type==='features'?'featuresSection':s.type==='contact'?'contactSection':'textSection'))}</span><span class="chev">⌄</span></summary><div class="section-content">${inputField('title','sectionTitle',s.title,'textarea',i)}${inputField('body','sectionBody',s.body,'textarea',i)}${s.type==='features'?`<p class="help-text">${t('featuresHint')}</p>`:''}<div class="section-tools"><button class="small-btn" data-move="${i}" data-step="-1" aria-label="${t('moveUp')}" ${i===0?'disabled':''}>↑</button><button class="small-btn" data-move="${i}" data-step="1" aria-label="${t('moveDown')}" ${i===p.sections.length-1?'disabled':''}>↓</button><button class="small-btn danger" data-delete-section="${i}">${t('delete')}</button></div></div></details>`).join('')}<button class="section-add" id="add-section">${t('addSection')}</button></div>`;}
html+=`<div class="field-group"><h3><span>◎</span>${t('targetLabel')}</h3>${p.published?`<p class="help-text site-address">${h(p.published.site)}</p><button class="text-button" id="detach-site">${t('detach')}</button>`:`<button class="text-button" id="attach-site">${t('attachSite')}</button>`}</div><div class="field-group"><button class="text-button" id="backup-btn">↓ ${t('projectBackup')}</button><div class="danger-zone"><button class="text-button" id="delete-project">${t('deleteProject')}</button></div></div>`;$('#inspector-fields').innerHTML=html;bindInspector();}
function bindInspector(){$$('[data-field]').forEach(e=>e.addEventListener('input',()=>{project()[e.dataset.field]=e.value;changed();}));$$('[data-section]').forEach(e=>e.addEventListener('input',()=>{project().sections[+e.dataset.section][e.dataset.key]=e.value;if(e.dataset.key==='title')e.closest('.section-item').querySelector('.section-name').textContent=e.value;changed();}));$('#page-language')?.addEventListener('change',e=>{project().lang=e.target.value;changed();});$('#entry-file')?.addEventListener('change',e=>{project().entry=e.target.value;changed();});$('#upload-logo')?.addEventListener('click',()=>$('#logo-input').click());$('#remove-logo')?.addEventListener('click',()=>{project().logo=null;renderInspector();changed();});for(const[key,id,code]of[['color','accent-color','accent-code'],['surface','surface-color','surface-code']])$('#'+id)?.addEventListener('input',e=>{project()[key]=e.target.value;$('#'+code).textContent=e.target.value.toUpperCase();changed();});$$('[data-color]').forEach(e=>e.onclick=()=>{project().color=e.dataset.color;renderInspector();changed();});$$('[data-move]').forEach(e=>e.onclick=()=>{const i=+e.dataset.move,j=i+(+e.dataset.step),s=project().sections;[s[i],s[j]]=[s[j],s[i]];renderInspector();changed();});$$('[data-delete-section]').forEach(e=>e.onclick=()=>{if(confirm(t('confirmSection'))){project().sections.splice(+e.dataset.deleteSection,1);renderInspector();changed();}});$('#add-section')?.addEventListener('click',addSection);$('#attach-site')?.addEventListener('click',attachSite);$('#detach-site')?.addEventListener('click',()=>{project().published=null;renderInspector();changed();renderSites();});$('#backup-btn').onclick=backup;$('#delete-project').onclick=()=>{if(confirm(t('confirmDelete'))){projects=projects.filter(p=>p.id!==currentId);if(!projects.length)projects.push(newProject('personal'));currentId=projects[0].id;persist();render();}};}
function renderPreview(){try{const p=project(),files=projectFiles(p);latestPreview=previewHTML(files,p.mode==='files'?p.entry:'/index.html');$('#preview').srcdoc=latestPreview;$('#size-state').textContent=`${files.length} ${t('fileLabel')} · ${bytes(files.reduce((n,f)=>n+f.data.length,0))} / 4 MiB`;$('#preview-note').hidden=p.mode!=='files';$('#preview-address').textContent=p.published?'pocol/'+p.published.site.slice(0,8)+'…':(p.mode==='files'?p.entry:'/index.html');scalePreview();}catch(e){$('#save-state').textContent=errorText(e);$('#save-state').classList.add('error-text');}}
function scalePreview(){const frame=$('#preview-frame'),iframe=$('#preview'),width=frame.clientWidth,w=device==='mobile'?375:1000,scale=width/w;iframe.style.width=w+'px';iframe.style.height=(frame.clientHeight-31)/scale+'px';iframe.style.transform=`scale(${scale})`;iframe.style.transformOrigin='top left';}
function renderFiles(){try{const files=projectFiles(project());$('#file-list').innerHTML=files.map((f,i)=>`<div class="file-row"><span class="file-type">${h(f.path.split('.').pop().toUpperCase())}</span><span class="file-name">${h(f.path)}</span><span class="file-bytes">${bytes(f.data.length)}</span>${/^text\/|javascript|json/.test(mimeFor(f.path))?`<button class="small-btn" data-file-index="${i}">${t('viewEdit')}</button>`:''}</div>`).join('');$$('[data-file-index]').forEach(b=>b.onclick=()=>viewFile(+b.dataset.fileIndex));}catch(e){$('#file-list').textContent=errorText(e);}}
function renderSites(){const sites=projects.filter(p=>p.published);$('#sites-list').innerHTML=sites.length?sites.map(p=>`<article class="site-card"><h3>${h(p.name)}</h3><div class="site-address">${h(p.published.site)}</div><div class="site-card-footer"><span class="site-card-meta">${t('version')} ${h(p.published.version??t('unavailable'))}${p.published.publishedBlock!=null?' · '+t('block')+' '+h(p.published.publishedBlock):''}</span><button class="button secondary" data-edit-site="${h(p.id)}">${t('edit')}</button><button class="button secondary" data-copy="${h(p.published.site)}">${t('copyAddress')}</button><button class="button primary" data-open-site="${h(p.published.site)}">${t('openSite')} ↗</button></div></article>`).join(''):`<div class="empty-state"><span>◎</span><h3>${t('noSites')}</h3><p>${t('noSitesText')}</p></div>`;$$('[data-edit-site]').forEach(b=>b.onclick=()=>{currentId=b.dataset.editSite;panel('design');render();settings();});$$('[data-copy]').forEach(b=>b.onclick=()=>copy(b.dataset.copy));$$('[data-open-site]').forEach(b=>b.onclick=()=>openSite(b.dataset.openSite));}
function render(){renderHeading();renderInspector();renderPreview();renderFiles();renderSites();}
function panel(name){activePanel=name;$$('.main-panel').forEach(e=>e.hidden=e.id!==name+'-panel');$$('[data-panel]').forEach(e=>e.classList.toggle('active',e.dataset.panel===name));if(name==='files')renderFiles();if(name==='sites')renderSites();if(name==='design')setTimeout(scalePreview,0);}
function modal(title,html,full=false){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#modal').classList.toggle('full-preview',full);if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){$('#modal').close();}
function templates(){modal(t('newTitle'),`<p class="modal-intro">${t('newIntro')}</p><div class="template-grid">${['personal','business','product'].map((id,i)=>`<button class="template-card ${id}" data-template="${id}" style="--template:${['#187b68','#147d8d','#6743c3'][i]}"><div class="template-art"><div class="line"></div><div class="line short"></div><div class="paragraph"></div><div class="paragraph short"></div><span class="orb"></span></div><span class="name">${t(id)}</span></button>`).join('')}</div><div class="template-caption"><span>${t('orImport')}</span><button class="text-button" id="modal-folder">${t('importFolder')}</button><button class="text-button" id="modal-project">${t('importProject')}</button></div>`);$$('[data-template]').forEach(b=>b.onclick=()=>{if(projects.length>=25){toast(t('projectLimit'),true);return;}const p=newProject(b.dataset.template);projects.unshift(p);currentId=p.id;panel('design');persist();render();closeModal();toast(t('templateCreated'));});$('#modal-folder').onclick=()=>$('#folder-input').click();$('#modal-project').onclick=()=>$('#project-input').click();}
function addSection(){if(project().sections.length>=20){toast(t('sectionLimit'));return;}modal(t('addSection').replace('＋',''),`<div class="modal-actions">${['text','features','contact'].map(type=>`<button class="button secondary" data-add-type="${type}">${t(type==='text'?'textSection':type==='features'?'featuresSection':'contactSection')}</button>`).join('')}</div>`);$$('[data-add-type]').forEach(b=>b.onclick=()=>{const type=b.dataset.addType;project().sections.push({id:uid(),type,title:strings[project().lang][type==='text'?'textSection':type==='features'?'featuresSection':'contactSection'],body:''});closeModal();renderInspector();changed();});}
function download(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function filename(){return'PoCol-'+project().id.slice(0,8);}
function backup(){download(new Blob([publicProject(project())],{type:'application/json'}),filename()+'.studio.json');toast(t('backupExported'));}
function exportSite(){try{download(zipFiles(projectFiles(project())),filename()+'.zip');toast(t('exported'));}catch(e){toast(errorText(e),true);}}
function help(){modal(t('helpTitle'),`<ol class="help-steps">${[1,2,3,4].map(i=>`<li><strong>${t('help'+i)}</strong>${t('help'+i+'Text')}</li>`).join('')}</ol><div class="notice warning">${t('testnetNote')}</div><p class="help-text">${t('privacy')}</p><div class="sources"><a target="_blank" rel="noreferrer" href="https://github.com/palcertcom/pocol/blob/50c2f27ee67961dec7aaf0eb735c0b641810e0ea/prototypes/pocold/src/site.rs">${t('source')} ↗</a><a target="_blank" rel="noreferrer" href="https://github.com/palcertcom/pocol/tree/50c2f27ee67961dec7aaf0eb735c0b641810e0ea/prototypes/pocol-extension">${t('extensionSource')} ↗</a></div><div class="modal-actions"><button class="button secondary" id="help-backup">${t('projectBackup')}</button><button class="button primary" id="help-install">${t('downloadExtension')}</button></div>`);$('#help-backup').onclick=backup;$('#help-install').onclick=install;}
function install(){modal(t('installTitle'),`<p class="modal-intro">${t('installIntro')}</p><ol class="help-steps">${[1,2,3,4].map(i=>`<li>${t('install'+i)}</li>`).join('')}</ol><div class="installation-path">chrome://extensions</div><div class="modal-actions"><a class="button primary" href="downloads/PoCol-Studio-IDE-Viewer-0.4.0.zip" download>${t('downloadExtension')} ↓</a><button class="button secondary" id="detect-extension">${t('checkExtension')}</button></div><p id="install-status" class="help-text"></p>`);$('#detect-extension').onclick=async()=>{try{await bridge('status',{},1800);$('#install-status').textContent=t('extensionReady');}catch{$('#install-status').textContent=t('extensionMissing');}};}
const pending=new Map();
window.addEventListener('message',e=>{if(e.source!==window||e.origin!==location.origin||e.data?.source!=='pocol-extension'||typeof e.data.id!=='string')return;const p=pending.get(e.data.id);if(!p)return;clearTimeout(p.timer);pending.delete(e.data.id);e.data.ok?p.resolve(e.data.result):p.reject(Error(String(e.data.error||t('unknownError'))));});
function bridge(method,payload={},timeout=10000){return new Promise((resolve,reject)=>{const id=uid(),timer=setTimeout(()=>{pending.delete(id);reject(Error('extensionMissing'));},timeout);pending.set(id,{resolve,reject,timer});window.postMessage({source:'pocol-studio',id,method,payload},location.origin);});}
async function publish(){if(job){showJob();return;}try{await bridge('status',{},1500);}catch{install();return;}const p=project();let files;try{files=projectFiles(p);}catch(e){toast(errorText(e),true);return;}modal(t('publishTitle'),`<p class="modal-intro">${t('reviewIntro')}</p><div class="job-summary"><div><span>${t('fileLabel')}</span><strong>${files.length}</strong></div><div><span>${t('sizeLabel')}</span><strong>${bytes(files.reduce((n,f)=>n+f.data.length,0))}</strong></div><div><span>${t('targetLabel')}</span><strong>${t(p.published?'existingSite':'newSite')}</strong></div></div>${p.published?`<div class="notice"><div class="site-address">${h(p.published.site)}</div><p>${t('updateWarning')}</p></div>`:''}<div class="notice">${t('offlinePublish')}</div><div class="modal-actions"><button class="button secondary" id="publish-cancel">${t('cancel')}</button><button class="button primary" id="publish-confirm">${t('openPublisher')} ↗</button></div>`);$('#publish-cancel').onclick=closeModal;$('#publish-confirm').onclick=async()=>{const btn=$('#publish-confirm');btn.disabled=true;try{const result=await bridge('openPublisher',{title:p.name,files:files.map(f=>({path:f.path,base64:encode64(f.data)})),entry:p.mode==='files'?p.entry:'/index.html',...(p.published?{site:p.published.site}:{})},20000);job={id:result.jobId,projectId:p.id,status:'awaitingApproval'};try{sessionStorage.setItem('pocol-studio-active-job',JSON.stringify({id:job.id,projectId:p.id}));}catch{}renderHeading();showJob();pollJob();}catch(e){toast(errorText(e),true);btn.disabled=false;}};}
function showJob(){if(!job)return;modal(t('publishTitle'),`<div class="status-banner"><span class="spinner"></span><span id="job-status">${t(job.status==='error'?'publishError':job.status)}</span></div><p class="job-detail" id="job-detail">${t('waitingResult')}</p><div class="notice">${t('keepTab')}<br>${t('historyHint')}</div><div id="job-result"></div>`);if(job.status==='complete'||job.status==='error'||job.status==='cancelled')renderJob();}
function renderJob(){if(!job)return;const el=$('#job-status');if(!el)return;el.textContent=t(job.status==='error'?'publishError':job.status);$('.status-banner .spinner')?.classList.toggle('saved-text',job.status==='complete');if(job.status==='complete'||job.status==='error'||job.status==='cancelled')$('.status-banner .spinner')?.remove();$('#job-detail').textContent=job.error||(job.progress?.phase?t('phase_'+job.progress.phase)+(job.progress.total?' · '+job.progress.completed+'/'+job.progress.total:''):t('waitingResult'));if(job.status==='complete'&&job.result){const r=job.result;$('#job-result').innerHTML=`<div class="job-result"><div class="site-address">${h(r.site)}</div><p class="help-text">${t('version')} ${h(r.version)}</p><div class="modal-actions"><button class="button secondary" id="result-copy">${t('copyAddress')}</button><button class="button primary" id="result-open">${t('openSite')} ↗</button><button class="button secondary" id="job-finish">${t('close')}</button></div></div>`;$('#result-copy').onclick=()=>copy(r.site);$('#result-open').onclick=()=>openSite(r.site);$('#job-finish').onclick=()=>{job=null;try{sessionStorage.removeItem('pocol-studio-active-job');}catch{}renderHeading();closeModal();};}else if(job.status==='error'||job.status==='cancelled'){$('#job-result').innerHTML=`<div class="modal-actions"><button class="button secondary" id="job-finish">${t('close')}</button></div>`;$('#job-finish').onclick=()=>{job=null;try{sessionStorage.removeItem('pocol-studio-active-job');}catch{}renderHeading();closeModal();};}}
async function pollJob(){if(!job)return;try{const s=await bridge('jobStatus',{jobId:job.id});if(!job)return;job={...job,...s};if(job.status==='complete'&&job.result){const p=projects.find(p=>p.id===job.projectId);if(p){p.published={site:job.result.site,version:job.result.version,publishedBlock:job.result.publishedBlock??null};p.updated=Date.now();persist();renderHeading();renderSites();}renderJob();return;}renderJob();if(job.status==='error'||job.status==='cancelled')return;jobTimer=setTimeout(pollJob,2000);}catch(e){if(job){job.error=t('jobLost');job.status='paused';renderJob();jobTimer=setTimeout(pollJob,5000);}}}
async function openSite(site){try{await bridge('openSite',{site,path:'/'});}catch{install();}}
async function copy(text){try{await navigator.clipboard.writeText(text);toast(t('copied'));}catch{toast(t('copyFailed'),true);}}
async function checkNetwork(){$('#network-state').textContent=t('checking');$('#network-dot').className='status-dot waiting';try{const r=await fetch('https://gateway.pocol.net/studio/health',{cache:'no-store',signal:AbortSignal.timeout(5000)});if(!r.ok)throw Error();const v=await r.json();const cid=v.chainId??v.network?.chainId;if(Number(cid)!==1599846715||v.genesisHash!=='0xbe137bfdb4fdf332f2e1500ee1a67e0b22ce6bdf57efa46fb4ea7b0debe509ca'){$('#network-state').textContent=t('networkMismatch');$('#network-dot').className='status-dot offline';return;}if(v.ready!==true&&v.ok!==true&&v.status!=='ok')throw Error();$('#network-state').textContent=t('networkConnected');$('#network-dot').className='status-dot';}catch{$('#network-state').textContent=t('networkOffline');$('#network-dot').className='status-dot offline';}}
function viewFile(index){const p=project(),files=projectFiles(p),f=files[index];modal(f.path,`<textarea class="file-source" id="file-source" spellcheck="false" ${p.mode==='visual'?'readonly':''}></textarea>${p.mode==='visual'?`<p class="help-text">${t('generatedNotice')}</p>`:''}<div class="modal-actions"><button class="button secondary" id="file-close">${t('close')}</button>${p.mode==='files'?`<button class="button primary" id="file-save">${t('saveFile')}</button>`:''}</div>`);$('#file-source').value=new TextDecoder().decode(f.data);$('#file-close').onclick=closeModal;$('#file-save')?.addEventListener('click',()=>{const data=new TextEncoder().encode($('#file-source').value),next=files.map((x,i)=>i===index?{...x,data}:x);try{validateFiles(next,p.entry);p.files[index].base64=encode64(data);changed();renderFiles();closeModal();}catch(e){toast(errorText(e),true);}});}
$('#folder-input').onchange=async e=>{const list=[...e.target.files];e.target.value='';if(!list.length)return;if(projects.length>=25){toast(t('projectLimit'),true);return;}if(list.length>256){toast(t('fileCount'),true);return;}if(list.some(f=>f.size>LIMITS.file)){toast(t('fileSize'),true);return;}if(list.reduce((n,f)=>n+f.size,0)>LIMITS.total){toast(t('totalSize'),true);return;}try{const files=await Promise.all(list.map(async f=>{const raw=f.webkitRelativePath||f.name,path='/'+(f.webkitRelativePath?raw.split('/').slice(1).join('/'):raw);return{path,data:new Uint8Array(await f.arrayBuffer())};}));const entry=files.some(f=>f.path==='/index.html')?'/index.html':files.find(f=>mimeFor(f.path)==='text/html')?.path;validateFiles(files,entry);const p={id:uid(),name:list[0].webkitRelativePath?.split('/')[0]||t('importedFiles'),mode:'files',lang,entry,files:files.map(f=>({path:f.path,base64:encode64(f.data)})),created:Date.now(),updated:Date.now(),published:null};projects.unshift(p);currentId=p.id;persist();panel('files');render();closeModal();toast(t('filesImported'));}catch(err){toast(errorText(err),true);}};
$('#project-input').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;if(projects.length>=25){toast(t('projectLimit'),true);return;}if(f.size>7*1048576){toast(t('totalSize'),true);return;}try{const p=parseProject(await f.text());p.id=uid();projects.unshift(p);currentId=p.id;persist();panel('design');render();closeModal();toast(t('imported'));}catch(err){toast(errorText(err),true);}};
$('#logo-input').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>200*1024||!['image/png','image/jpeg','image/webp'].includes(f.type)){toast(t('logoSize'),true);return;}try{const bitmap=await createImageBitmap(f);bitmap.close();project().logo={mime:f.type,base64:encode64(new Uint8Array(await f.arrayBuffer()))};renderInspector();changed();}catch{toast(t('logoInvalid'),true);}};
$('#new-btn').onclick=templates;$('#export-btn').onclick=exportSite;$('#publish-btn').onclick=publish;$('#help-btn').onclick=help;$('#guide-btn').onclick=help;$('#network-retry').onclick=checkNetwork;$('#import-folder-btn').onclick=()=>$('#folder-input').click();$('#modal-close').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});$('#lang-btn').onclick=()=>{lang=lang==='ar'?'en':'ar';setLocale();checkNetwork();};$('#theme-btn').onclick=()=>{theme=theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;settings();};$('#project-select').onchange=e=>{persist();currentId=e.target.value;settings();render();};$$('[data-panel]').forEach(e=>e.onclick=()=>panel(e.dataset.panel));for(const mode of['desktop','mobile'])$('#'+mode+'-btn').onclick=()=>{device=mode;$('#preview-frame').classList.toggle('mobile',mode==='mobile');for(const m of['desktop','mobile']){$('#'+m+'-btn').classList.toggle('active',m===mode);$('#'+m+'-btn').setAttribute('aria-pressed',String(m===mode));}setTimeout(scalePreview,270);};$('#preview-btn').onclick=()=>{modal(t('preview'),'<iframe id="full-preview" sandbox="" referrerpolicy="no-referrer" title="Site preview" tabindex="-1"></iframe>',true);$('#full-preview').srcdoc=latestPreview;};new ResizeObserver(scalePreview).observe($('#preview-frame'));window.addEventListener('beforeunload',()=>persist());
setLocale();persist();checkNetwork();restoreJob();

function attachSite(){modal(t('attachSite'),`<p class="modal-intro">${t('attachIntro')}</p><div class="field"><label for="attach-address">${t('siteAddress')}</label><input id="attach-address" dir="ltr" placeholder="0x…" autocomplete="off" spellcheck="false" maxlength="42"></div><div class="modal-actions"><button class="button secondary" id="attach-cancel">${t('cancel')}</button><button class="button primary" id="attach-confirm">${t('attach')}</button></div>`);$('#attach-cancel').onclick=closeModal;$('#attach-confirm').onclick=()=>{const site=$('#attach-address').value.trim();if(!/^0x[0-9a-f]{40}$/i.test(site)||/^0x0{40}$/i.test(site)){toast(t('invalidAddress'),true);return;}project().published={site:site.toLowerCase(),version:null,publishedBlock:null,attached:true};changed();renderInspector();renderSites();closeModal();};}
async function restoreJob(){try{const saved=JSON.parse(sessionStorage.getItem('pocol-studio-active-job')||'null');if(!saved?.id||!projects.some(p=>p.id===saved.projectId))return;const status=await bridge('status',{},1800),found=status.jobs?.find(j=>j.jobId===saved.id);if(!found)return;job={id:saved.id,projectId:saved.projectId,status:found.status};renderHeading();pollJob();}catch{}}
